function validate([num, k]) {
  if (typeof num !== 'string' || num.length < 2 || num.length > 1000) return 'num needs 2 to 1000 digits.';
  if (!/^[0-9]+$/.test(num)) return 'num may contain only digits.';
  if (!Number.isInteger(k) || k < 1 || k > 1000) return 'k must be an integer from 1 to 1000.';
  const d = num.split('');
  for (let count = 0; count < k; count++) {
    let p = d.length - 2;
    while (p >= 0 && d[p] >= d[p + 1]) p--;
    if (p < 0) return 'Fewer than k larger numbers can be made from these digits.';
    let q = d.length - 1;
    while (d[q] <= d[p]) q--;
    [d[p], d[q]] = [d[q], d[p]];
    for (let l = p + 1, r = d.length - 1; l < r; l++, r--) [d[l], d[r]] = [d[r], d[l]];
  }
  return null;
}

