    let left = pivot + 1;
    let right = target.length - 1;
    while (left < right) {
      [target[left], target[right]] = [target[right], target[left]];
      left++;
      right--;
    }
  }

  const current = num.split('');
  let swaps = 0;
  for (let i = 0; i < current.length; i++) {
    let j = i;
    while (current[j] !== target[i]) {
      j++;
    }
    while (j > i) {
      [current[j - 1], current[j]] = [current[j], current[j - 1]];
      j--;
      swaps++;
    }
  }
  return swaps;
}

