function getMinSwaps(num, k) {
  const n = num.length;
  // The k smallest larger arrangements keep the longest possible prefix, so list every
  // arrangement of ever longer suffixes until one has at least k larger arrangements.
  let target = null;
  for (let size = 1; size <= n && target === null; size++) {
    const prefix = num.slice(0, n - size);
    const suffix = num.slice(n - size);
    const all = new Set();
    const build = (rest, built) => {
      if (rest.length === 0) {
        all.add(built);
        return;
      }
      for (let i = 0; i < rest.length; i++) {
        if (rest.indexOf(rest[i]) !== i) continue;
        build(rest.slice(0, i) + rest.slice(i + 1), built + rest[i]);
      }
    };
    build(suffix, '');
    const larger = [...all].filter(s => s > suffix).sort();
    if (larger.length >= k) target = prefix + larger[k - 1];
  }
  // Fewest neighbour swaps = number of inversions once equal digits keep their order.
  const queues = new Map();
  for (let i = 0; i < n; i++) {
    if (!queues.has(num[i])) queues.set(num[i], []);
    queues.get(num[i]).push(i);
  }
  const origin = [];
  for (const ch of target) origin.push(queues.get(ch).shift());
  let inversions = 0;
  for (let a = 0; a < n; a++) {
    for (let b = a + 1; b < n; b++) if (origin[a] > origin[b]) inversions++;
  }
  return inversions;
}

