function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  // Counts how many next-permutation steps are possible, stopping at limit.
  const stepsAvailable = (num, limit) => {
    const d = num.split('');
    let count = 0;
    while (count < limit) {
      let p = d.length - 2;
      while (p >= 0 && d[p] >= d[p + 1]) p--;
      if (p < 0) break;
      let q = d.length - 1;
      while (d[q] <= d[p]) q--;
      [d[p], d[q]] = [d[q], d[p]];
      for (let l = p + 1, r = d.length - 1; l < r; l++, r--) [d[l], d[r]] = [d[r], d[l]];
      count++;
    }
    return count;
  };
  for (;;) {
    let num = '';
    if (size === 'small') {
      const n = int(2, 7);
      const pool = [2, 3, 10][int(0, 2)];
      for (let i = 0; i < n; i++) num += String(int(0, pool - 1));
      const available = stepsAvailable(num, 1000);
      if (available === 0) continue;
      return [num, int(1, available)];
    }
    const mode = rand();
    const n = int(900, 1000);
    if (mode < 0.4) {
      for (let i = 0; i < n; i++) num += String(int(0, 9));
    } else if (mode < 0.7) {
      for (let i = 0; i < n; i++) num += String(int(0, 1));
    } else {
      // A falling run of digits followed by a short random tail.
      const digits = [];
      for (let i = 0; i < n - 12; i++) digits.push(int(0, 9));
      digits.sort((a, b) => b - a);
      for (let i = 0; i < 12; i++) digits.push(int(0, 9));
      num = digits.join('');
    }
    const k = rand() < 0.5 ? 1000 : int(1, 1000);
    if (stepsAvailable(num, k) === k) return [num, k];
  }
}
